using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using MapSharedProps;
public static class Lantern168BudgetChecks{
 public static void Run(){string dir=Path.Combine(Path.GetDirectoryName(Application.dataPath),"Evidence168");Directory.CreateDirectory(dir);try{EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var root=new GameObject("Budget transition");var list=new List<RoomTorchInstance>();foreach(float x in new[]{0f,35f,70f}){var go=new GameObject("lamp"+x);go.transform.SetParent(root.transform);go.transform.position=new Vector3(x,1.65f,0);var f=go.AddComponent<RoomTorchInstance>();f.ConfigureLamp(Vector3.zero,3.2f,5.5f,"lamp"+x);list.Add(f);}var b=root.AddComponent<RoomTorchBudget>();b.Configure(list.ToArray());int max=0;foreach(float x in new[]{0f,35f,70f,100f,35f,0f,200f}){for(int j=0;j<90;j++){b.Tick(1/30f,new Vector3(x,0,0));int n=root.GetComponentsInChildren<Light>().Count(l=>l.enabled&&l.intensity>0);max=Math.Max(max,n);if(n>2)throw new Exception("pool exceeded "+n);}if(x==200f&&root.GetComponentsInChildren<Light>().Any(l=>l.enabled))throw new Exception("orphan lamp after focus leaves");}foreach(var f in list)f.gameObject.SetActive(false);for(int j=0;j<90;j++)b.Tick(1/30f,Vector3.zero);if(root.GetComponentsInChildren<Light>().Any(l=>l.enabled))throw new Exception("orphan disabled fixture");File.WriteAllText(Path.Combine(dir,"budget.json"),"{\"pass\":true,\"maxActive\":"+max+",\"focusTransitions\":7,\"orphanLights\":0}");UnityEngine.Object.DestroyImmediate(root);EditorApplication.Exit(0);}catch(Exception e){File.WriteAllText(Path.Combine(dir,"error.txt"),e.ToString());Debug.LogException(e);EditorApplication.Exit(1);}}
}
